1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export interface QuoteStep {
23	  op: "quote";
24	  items: Item[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	
57	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	  rune: 25,
65	  moonstone: 25,
66	} as const satisfies Record<string, number>;
67	
68	type PricedItemType = keyof typeof BASE_PREMIUMS;
69	
70	const hasBasePremium = (type: string): type is PricedItemType =>
71	  type in BASE_PREMIUMS;
72	
73	// Unknown item types are not yet rejected — the spec requires an error, but no
74	// test drives that behaviour yet, so they are priced at 0 for the moment.
75	const UNPRICED_UNKNOWN_TYPE = 0;
76	
77	const basePremiumForItem = (item: Item): number =>
78	  hasBasePremium(item.type)
79	    ? BASE_PREMIUMS[item.type]
80	    : UNPRICED_UNKNOWN_TYPE;
81	
82	const BLOCK_SIZE = 3;
83	
84	const BLOCK_BASE_PREMIUM = 60;
85	
86	const sum = (amounts: number[]): number =>
87	  amounts.reduce((total, amount) => total + amount, 0);
88	
89	// "Alike" means the same exact type, not merely the same family: two runes and
90	// a moonstone are three components but not three alike ones, so grouping them
91	// by type keeps them apart and denies them the block price.
92	const groupByType = (items: Item[]): Item[][] => {
93	  const groups = new Map<string, Item[]>();
94	  for (const item of items) {
95	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
96	  }
97	  return [...groups.values()];
98	};
99	
100	// A block is not carved out of a larger group: the block price applies only
101	// when the group consists of exactly three alike components (7 runes cost
102	// 7 × 25, not 60 + 60 + 25). Alikeness is guaranteed by the caller, which only
103	// ever passes a single group from groupByType.
104	const basePremiumForGroup = (group: Item[]): number =>
105	  group.length === BLOCK_SIZE
106	    ? BLOCK_BASE_PREMIUM
107	    : sum(group.map(basePremiumForItem));
108	
109	const basePremiumForItems = (items: Item[]): number =>
110	  sum(groupByType(items).map(basePremiumForGroup));
111	
112	const CURSE_SURCHARGE = 0.5;
113	
114	// Every modifier is an additive percentage of its OWN base — modifiers never
115	// compound with each other. Item-scoped modifiers take the affected item's base
116	// premium as their base; policy-scoped modifiers take the policy base premium
117	// (the sum of all item base premiums). So the total is always
118	// base + Σ (rate × that modifier's base), never a product of (1 + rate) factors.
119	const modifierAmount = (rate: number, base: number): number => rate * base;
120	
121	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
122	
123	const HIGH_ENCHANTMENT_THRESHOLD = 5;
124	
125	const isCursed = (item: Item): boolean => item.cursed === true;
126	
127	const isHighlyEnchanted = (item: Item): boolean =>
128	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
129	
130	interface ItemModifier {
131	  rate: number;
132	  appliesTo: (item: Item) => boolean;
133	}
134	
135	// Each item-scoped modifier is a row: a rate and the condition under which it
136	// applies. The predicate names the modifier, so a row needs no separate label.
137	// Adding a modifier means adding a row, not a new branch.
138	const ITEM_MODIFIERS: ItemModifier[] = [
139	  { rate: CURSE_SURCHARGE, appliesTo: isCursed },
140	  { rate: HIGH_ENCHANTMENT_SURCHARGE, appliesTo: isHighlyEnchanted },
141	];
142	
143	const itemModifierRates = (item: Item): number[] =>
144	  ITEM_MODIFIERS.filter((modifier) => modifier.appliesTo(item)).map(
145	    (modifier) => modifier.rate,
146	  );
147	
148	const LOYALTY_DISCOUNT = 0.2;
149	
150	const LOYALTY_THRESHOLD_YEARS = 2;
151	
152	const isLongStanding = (customer: Customer): boolean =>
153	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
154	
155	// Discounts are surcharges with the sign flipped: expressing one as a negative
156	// rate lets it flow through the same additive sum as every surcharge, with no
157	// separate subtraction step. Discount constants stay positive magnitudes and
158	// are negated here, at the point of use, so the direction is visible in the
159	// rate list rather than buried in a constant's sign.
160	const asDiscount = (rate: number): number => -rate;
161	
162	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
163	
164	// Policy-scoped modifiers apply to the policy base premium. Unlike item
165	// modifiers they select on the customer and on the quote's position in the
166	// scenario rather than on an item.
167	//
168	// The initial-assessment surcharge applies to every quote: each item is treated
169	// as a first insurance regardless of customer history. The follow-up discount
170	// is what distinguishes a customer's later contracts.
171	const policyModifierRates = (
172	  customer: Customer,
173	  isFollowUpContract: boolean,
174	): number[] => [
175	  INITIAL_ASSESSMENT_SURCHARGE,
176	  ...(isLongStanding(customer) ? [asDiscount(LOYALTY_DISCOUNT)] : []),
177	  ...(isFollowUpContract ? [asDiscount(FOLLOW_UP_CONTRACT_DISCOUNT)] : []),
178	];
179	
180	const itemModifiersTotal = (items: Item[]): number =>
181	  sum(
182	    items.flatMap((item) =>
183	      itemModifierRates(item).map((rate) =>
184	        modifierAmount(rate, basePremiumForItem(item)),
185	      ),
186	    ),
187	  );
188	
189	const policyModifiersTotal = (
190	  policyBasePremium: number,
191	  customer: Customer,
192	  isFollowUpContract: boolean,
193	): number =>
194	  sum(
195	    policyModifierRates(customer, isFollowUpContract).map((rate) =>
196	      modifierAmount(rate, policyBasePremium),
197	    ),
198	  );
199	
200	// All amounts are rounded to whole G in the MHPCO's favour. For a premium —
201	// money flowing to the MHPCO — its favour is upwards. The payout half of this
202	// rule rounds the other way, but no test drives payouts yet, so only the
203	// premium direction is named here.
204	const roundPremiumInMHPCOsFavour = (amount: number): number =>
205	  Math.ceil(amount);
206	
207	const quotePremium = (
208	  items: Item[],
209	  customer: Customer,
210	  isFollowUpContract: boolean,
211	): number => {
212	  const policyBasePremium = basePremiumForItems(items);
213	  return roundPremiumInMHPCOsFavour(
214	    policyBasePremium +
215	      itemModifiersTotal(items) +
216	      policyModifiersTotal(policyBasePremium, customer, isFollowUpContract) +
217	      PROCESSING_FEE,
218	  );
219	};
220	
221	// Steps are not independent: a quote's premium depends on how many quotes came
222	// before it, and the pending claim operation will depend on the policies those
223	// quotes created. So a step is a function from state to (result, next state),
224	// and the scenario is a fold over that — not a map, which would promise an
225	// independence the steps do not have.
226	interface ScenarioState {
227	  quotesSoFar: number;
228	}
229	
230	const INITIAL_STATE: ScenarioState = { quotesSoFar: 0 };
231	
232	interface StepOutcome {
233	  result: StepResult;
234	  state: ScenarioState;
235	}
236	
237	const runQuote = (
238	  step: QuoteStep,
239	  customer: Customer,
240	  state: ScenarioState,
241	): StepOutcome => ({
242	  result: {
243	    premium: quotePremium(step.items, customer, state.quotesSoFar > 0),
244	  },
245	  state: { ...state, quotesSoFar: state.quotesSoFar + 1 },
246	});
247	
248	// Dispatch decides once what a step is; each operation then owns both its
249	// result and how it advances the state, so no caller has to re-test step.op to
250	// know what the step did.
251	const runStep = (
252	  step: Step,
253	  customer: Customer,
254	  state: ScenarioState,
255	): StepOutcome => {
256	  if (step.op === "quote") return runQuote(step, customer, state);
257	  throw new Error(`Unsupported step: ${step.op}`);
258	};
259	
260	// The fold carries both halves of the outcome: the results accumulated so far
261	// and the state the next step will see. Threading the state explicitly (rather
262	// than recovering it from the last result) keeps the dependency between steps
263	// visible in the type.
264	interface ScenarioRun {
265	  results: StepResult[];
266	  state: ScenarioState;
267	}
268	
269	const INITIAL_RUN: ScenarioRun = { results: [], state: INITIAL_STATE };
270	
271	const appendStep =
272	  (customer: Customer) =>
273	  (run: ScenarioRun, step: Step): ScenarioRun => {
274	    const outcome = runStep(step, customer, run.state);
275	    return {
276	      results: [...run.results, outcome.result],
277	      state: outcome.state,
278	    };
279	  };
280	
281	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => ({
282	  results: steps.reduce(appendStep(customer), INITIAL_RUN).results,
283	});
